local function decode(value)
    if type(value) ~= "table" then return value end
    local tag = value[1]
    if tag == "v2" then return Vector2.new(value[2], value[3]) end
    if tag == "v3" then return Vector3.new(value[2], value[3], value[4]) end
    if tag == "c3" then return Color3.new(value[2], value[3], value[4]) end
    if tag == "cf" then return CFrame.new(table.unpack(value, 2)) end
    if tag == "ud" then return UDim.new(value[2], value[3]) end
    if tag == "u2" then return UDim2.new(value[2], value[3], value[4], value[5]) end
    if tag == "enum" then
        local enumType, item = value[2]:match("^Enum%.([^.]+)%.(.+)$")
        return Enum[enumType][item]
    end
    if tag == "font" then
        return Font.new(value[2], Enum.FontWeight[value[3]], Enum.FontStyle[value[4]])
    end
    if tag == "rect" then
        return Rect.new(value[2], value[3], value[4], value[5])
    end
    if tag == "colors" then
        local points = {}
        for i = 2, #value do
            local p = value[i]
            points[#points + 1] = ColorSequenceKeypoint.new(p[1], Color3.new(p[2], p[3], p[4]))
        end
        return ColorSequence.new(points)
    end
    if tag == "numbers" then
        local points = {}
        for i = 2, #value do
            local p = value[i]
            points[#points + 1] = NumberSequenceKeypoint.new(p[1], p[2], p[3])
        end
        return NumberSequence.new(points)
    end
    error("Unsupported value type: " .. tostring(tag))
end

