local compressed = EncodingService:Base64Decode(buffer.fromstring(encoded))
local bytes = EncodingService:GetDecompressedBufferSize(compressed, Enum.CompressionAlgorithm.Zstd)
assert(bytes and bytes <= 100000000, "Invalid or oversized compressed map data")
local raw = EncodingService:DecompressBuffer(compressed, Enum.CompressionAlgorithm.Zstd)
local payload = HttpService:JSONDecode(buffer.tostring(raw))
local schemas, records = payload[1], payload[2]

for _, row in ipairs(records) do
    n += 1
    local parentId, class, name, changes = row[1], row[2], row[3], row[4]
    local ok, obj = pcall(Instance.new, class)
    if ok then
        obj.Name = name
        for _, change in ipairs(changes) do
            local property = schemas[class] and schemas[class][change[1]]
            local success, message = pcall(function()
                if not property then error("Missing schema property") end
                obj[property] = decode(change[2])
            end)
            if not success then
                failures += 1
                if failures <= 20 then
                    warn("Property failed:", class, name, property, message)
                end
            end
        end
        obj.Parent = created[parentId] or root
        created[n] = obj
    else
        failures += 1
        if failures <= 20 then warn("Instance failed:", class, name, obj) end
    end
    if n % 200 == 0 then task.wait() end
end
root.Parent = workspace
print("V2.2 reconstructed:", n, "objects; property/creation errors:", failures)
